<template><view class="sub-page"><view class="nav"><text @tap="back">‹</text><b>{{ article.title }}</b><text class="share" @tap="share">分享</text></view><view class="body"><view class="cover">平台公告</view><text class="title">{{ article.title }}</text><view class="meta"><text>{{ article.date }}</text><text>平台运营</text></view><view class="line"/><rich-text :nodes="article.content" /></view></view></template>
<script setup>import{computed,onMounted,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{enforcePortal}from'../../core/route-guard';const type=ref('notice'),id=ref('1');onLoad(o=>{type.value=o?.type||'notice';id.value=o?.id||'1'});onMounted(()=>enforcePortal('agent'));const article=computed(()=>type.value==='script'?{title:id.value==='2'?'新商家入驻权益说明':'如何邀请商家入驻',date:'2026-07-31',content:'<p class="article-paragraph">邀请商家时，请先向对方介绍平台服务与入驻流程。</p><p class="article-paragraph"><span class="article-strong">操作步骤</span></p><p class="article-paragraph">1. 打开邀请商家页面，复制专属邀请链接。<br/>2. 将链接发送给商家，指导其完成资料填报。<br/>3. 商家审核通过后，即可自动建立绑定关系。</p>'}:{title:id.value==='1'?'2月佣金调整':'平台运营通知',date:'2026-07-31',content:'<p class="article-paragraph">为了持续优化代理人服务体验，平台将对近期佣金结算规则进行说明。</p><p class="article-paragraph">佣金以最终结算数据为准，具体到账时间请以收益明细页面展示为准。</p><p class="article-paragraph">如有疑问，请联系平台运营团队。</p>'});function back(){uni.navigateBack()}function share(){uni.setClipboardData({data:`${article.value.title} - Friendship`,success:()=>uni.showToast({title:'内容已复制，可粘贴分享',icon:'none'})})}</script>
<style lang="scss" scoped>.sub-page{min-height:100vh;background:#fff;color:#27314a}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;border-bottom:1rpx solid #edf0f4;box-sizing:border-box;font-size:29rpx}.nav>text{width:76rpx;color:#5865f2;font-size:60rpx;line-height:1}.nav .share{font-size:25rpx;text-align:right}.nav b{flex:1;overflow:hidden;text-align:center;text-overflow:ellipsis;white-space:nowrap}.body{padding:34rpx}.cover{display:flex;align-items:center;justify-content:center;height:300rpx;border-radius:24rpx;background:linear-gradient(135deg,#e8ebff,#cdd3ff);color:#5966f3;font-size:42rpx;font-weight:750;letter-spacing:3rpx}.title{display:block;margin-top:36rpx;font-size:42rpx;font-weight:760;line-height:1.35}.meta{display:flex;justify-content:space-between;margin-top:21rpx;color:#99a2b2;font-size:21rpx}.line{height:1rpx;margin:28rpx 0;background:#edf0f4}.body :deep(.article-paragraph){margin:0 0 24rpx;color:#526078;font-size:27rpx;line-height:1.9}.body :deep(.article-strong){color:#27314a;font-weight:700}</style>
